var TABLE = {"Uwimana": "From uwi- (one who is) + Imana (God): 'one who is of God'.", "Nshimiyimana": "From n- (I) + shimiye (I am glad) + Imana expressing gladness in God.", "Kundimana": "From kund- (love me) + Imana: 'love me, God'.", "Mbabazimana": "From mbabazi (mercy) + Imana: 'mercy of God'.", "Ishimweman": "From ishimwe (praise) + mana: 'praise of God'.", "Tuyisengemana": "From tuyisenge (let us pray) + Imana: 'let us pray to God'.", "Rwamana": "From Rwanda + Imana: Signature clan-style surname, 'Rwanda of God'.", "Mbarimana": "From mbari (family/lineage) + Imana: Signature surname, 'family of God'.", "Sangwamana": "From sangwa (found/encountered) + Imana: Signature surname.", "Zirimana": "From zira (be blessed?) built on -mana: Signature surname in the Imana pattern."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
